#include <cstdio>

#include "commands.h"

namespace iree_tracy_profile {

void PrintAgentsMarkdown(FILE* out) {
  fputs(
      "# Tracy captures with iree-tracy-profile\n"
      "\n"
      "Use `iree-tracy-profile` to inspect `.tracy` captures produced by an\n"
      "IREE runtime built with Tracy instrumentation. Prefer `--format=jsonl`\n"
      "for automated analysis: each line is one independent JSON object keyed\n"
      "by `type` that can be filtered with `jq`.\n"
      "\n"
      "## Capture\n"
      "\n"
      "Start the capture tool, then run the workload with `TRACY_NO_EXIT=1`\n"
      "so the process waits until the trace has been transferred:\n"
      "\n"
      "```shell\n"
      "iree-tracy-capture -o run.tracy -f &\n"
      "TRACY_NO_EXIT=1 iree-benchmark-module --device=amdgpu \\\n"
      "    --module=model.vmfb --function=main --benchmark_min_time=20x \\\n"
      "    --device_profiling_mode=dispatch-events,device-queue-events \\\n"
      "    --device_profiling_tracy\n"
      "```\n"
      "\n"
      "`--device_profiling_tracy` forwards the HAL profiler's device\n"
      "timestamps (AMDGPU, Vulkan, local CPU) as GPU zones on contexts named\n"
      "`dev<N>/q<M> <lane>` with lanes `dispatch`, `queue`, `host`, `submit`.\n"
      "HIP/CUDA record dispatch zones directly with `--hip_tracing=2` /\n"
      "`--cuda_tracing=2` (contexts named after the device).\n"
      "\n"
      "## Start here\n"
      "\n"
      "```shell\n"
      "iree-tracy-profile summary run.tracy      # what is in the capture\n"
      "iree-tracy-profile explain run.tracy      # where the time goes + "
      "hints\n"
      "```\n"
      "\n"
      "## Record types (JSONL)\n"
      "\n"
      "All times are nanoseconds. `*_ns` fields are on Tracy's capture\n"
      "timeline; `since_start_ns` is relative to the first event. Aggregate\n"
      "rows share `count`, `total_ns`, `avg_ns`, `min_ns`, `max_ns`,\n"
      "`stddev_ns`, `p50_ns`, `p90_ns`, `p99_ns`. GPU rows share `context`,\n"
      "`context_name`, `lane`, `physical_device_ordinal`, `queue_ordinal`\n"
      "(the last two are null unless the context was produced by the HAL\n"
      "profile sink).\n"
      "\n"
      "| command | type | key fields |\n"
      "| --- | --- | --- |\n"
      "| summary | `summary` | capture_name, span_ns, cpu_zone_count, "
      "gpu_zone_count, message_count, failure |\n"
      "| summary | `summary_thread` | thread, thread_name, zone_count, "
      "busy_ns, busy_fraction |\n"
      "| summary | `summary_gpu_context` | context, lane, zone_count, "
      "total_ns, busy_ns, busy_fraction |\n"
      "| statistics | `statistics_row` | row_type (cpu_zone, gpu_zone, "
      "message_severity, plot, memory_pool, frame_set), event_name, "
      "aggregates, self_total_ns |\n"
      "| dispatch | `dispatch_group` | key, context, aggregates, share, "
      "unresolved_count |\n"
      "| dispatch --dispatch_events | `dispatch_event` | event_id, key, "
      "gpu_start_ns, gpu_end_ns, duration_ns, thread |\n"
      "| queue | `queue_group` / `queue_event` | same shape as dispatch, lanes "
      "queue/submit |\n"
      "| zone | `zone_group` | key, function, file, line, aggregates, "
      "self_total_ns, thread_count |\n"
      "| zone --zone_events | `zone_event` | event_id, key, thread, depth, "
      "start_ns, end_ns, duration_ns, self_ns, text |\n"
      "| thread | `thread` | thread, thread_name, zone_count, message_count, "
      "sample_count, busy_ns |\n"
      "| message | `message` | time_ns, thread, severity, source, text |\n"
      "| plot | `plot` / `plot_sample` | name, plot_type, count, min, max, avg "
      "/ time_ns, value |\n"
      "| memory | `memory_pool` / `memory_event` | pool, allocation_count, "
      "live_bytes, high_water_bytes / ptr, size, alloc_time_ns, free_time_ns "
      "|\n"
      "| frame | `frame_set` / `frame_event` | frame_set, count, aggregates / "
      "index, start_ns, end_ns |\n"
      "| explain | `explain_span`, `explain_context`, `explain_top_dispatch`, "
      "`explain_top_queue`, `explain_top_cpu_self`, `explain_thread`, "
      "`explain_hint` | ranked rows with share fractions; hints carry severity "
      "+ message |\n"
      "| cat | every event row type above plus `gpu_context` | raw dump |\n"
      "\n"
      "## Recipes\n"
      "\n"
      "Top dispatches by total device time:\n"
      "\n"
      "```shell\n"
      "iree-tracy-profile dispatch --format=jsonl run.tracy | \\\n"
      "  jq -c 'select(.type==\"dispatch_group\") | "
      "{key,count,total_ns,avg_ns,p99_ns,share}'\n"
      "```\n"
      "\n"
      "Every event of one kernel slower than 1ms, then drill into one by id:\n"
      "\n"
      "```shell\n"
      "iree-tracy-profile dispatch --format=jsonl --dispatch_events \\\n"
      "  --filter='*matmul*' run.tracy | jq -c 'select(.duration_ns > "
      "1000000)'\n"
      "iree-tracy-profile dispatch --id=1234 run.tracy\n"
      "```\n"
      "\n"
      "Host-side hot spots (self time excludes child zones):\n"
      "\n"
      "```shell\n"
      "iree-tracy-profile zone --format=jsonl run.tracy | \\\n"
      "  jq -c 'select(.type==\"zone_group\") | "
      "{key,count,self_total_ns,file,line}' | head\n"
      "```\n"
      "\n"
      "Device idle gaps: compare `busy_ns` against `span_ns` on\n"
      "`summary_gpu_context` rows, or read the `explain_hint` rows.\n"
      "\n"
      "Warnings emitted by the runtime or the profile sink:\n"
      "\n"
      "```shell\n"
      "iree-tracy-profile message --format=jsonl run.tracy | \\\n"
      "  jq -c 'select(.severity==\"warning\" or .severity==\"error\")'\n"
      "```\n"
      "\n"
      "Render a Perfetto timeline from the interchange export:\n"
      "\n"
      "```shell\n"
      "iree-tracy-profile export --format=ireeperf-jsonl --output=- run.tracy "
      "| \\\n"
      "  iree-profile-render --format=perfetto - -o run.pftrace\n"
      "```\n"
      "\n"
      "## Cross-referencing\n"
      "\n"
      "* `event_id` values are stable for one trace file: use them with "
      "`--id`\n"
      "  to fetch a single `dispatch_event`, `queue_event`, or `zone_event`.\n"
      "* `thread` ids join `zone_event`, `message`, `memory_event`, and\n"
      "  `thread` rows.\n"
      "* `context` ids join `dispatch_*`, `queue_*`, `summary_gpu_context`,\n"
      "  and `gpu_context` rows.\n"
      "* A `dispatch_event` and its enclosing `queue_event` on the same\n"
      "  device/queue overlap in time: join on `physical_device_ordinal`,\n"
      "  `queue_ordinal`, and `gpu_start_ns <= x < gpu_end_ns`.\n",
      out);
}

}  // namespace iree_tracy_profile
